# --- finalize: ensure section-8 header present, write files, assertions ---
for cid in IDS:
    b = P[cid]["basis"]
    if "第八节功量核标目段" not in b:
        b = b.replace("\n功量清单：", "\n第八节功量核标目段：功量清单：", 1)
        P[cid]["basis"] = b
    assert P[cid]["basis"].splitlines()[0] == "liuyao", cid
    assert "第八节功量核标目段" in P[cid]["basis"] and "主线认定" in P[cid]["basis"], cid
    assert "systems_used" in P[cid]["basis"], cid
assert set(P.keys()) == set(IDS), "id set mismatch"
assert len(P) == 20, len(P)
BASE.mkdir(parents=True, exist_ok=True)
for cid in IDS:
    (BASE / (cid + ".json")).write_text(json.dumps(P[cid], ensure_ascii=False, indent=1), encoding="utf-8")
written = [cid for cid in IDS if (BASE / (cid + ".json")).exists()]
assert len(written) == 20, written
cm = sum(1 for c in IDS if P[c]["trigger"]["changed_main"])
ru = sum(1 for c in IDS if P[c]["trigger"]["reserve_used"])
di = sum(1 for c in IDS if P[c]["trigger"]["disputed"])
print("CASES", len(IDS), "WRITTEN", len(written))
print("TRIGGER changed_main", cm, "reserve_used", ru, "disputed", di)
